const fields = $input.item.json.body.data.fields || [];
let parsedData = {};

fields.forEach(f => {
    // Вытягиваем скрытое поле. В Tally скрытые поля обычно имеют key, совпадающий с названием
    if (f.key === "contact_id" || f.label === "contact_id") {
        parsedData.contact_id = f.value;
    } else {
        // Вытягиваем остальные ответы
        parsedData[f.label] = f.value || "Не заполнено";
    }
});

// ПРЕДОХРАНИТЕЛЬ:
if (!parsedData.contact_id) {
    throw new Error("ОШИБКА: Форма заполнена без contact_id! Клиент перешел по прямой ссылке.");
}

return { json: parsedData };

try {
    const rawData = $input.first().json.data;
    const parsedData = JSON.parse(rawData);

    // Проверяем, есть ли вообще заметки
    if (!parsedData._embedded || !parsedData._embedded.notes || parsedData._embedded.notes.length === 0) {
        return []; // Если пусто - тихо останавливаемся
    }

    const notes = parsedData._embedded.notes;

    // БЕРЕМ СТРОГО КРАЙНЮЮ (ПОСЛЕДНЮЮ) ЗАМЕТКУ ИЗ МАССИВА
    const latestNote = notes[notes.length - 1]; 

    // Конвертируем время для этой единственной заметки
    const dateObj = new Date(latestNote.created_at * 1000);
    const dateStr = dateObj.toLocaleString('ru-RU', {
        day: '2-digit', month: '2-digit', year: 'numeric',
        hour: '2-digit', minute: '2-digit',
        timeZone: 'Europe/Kyiv'
    });

    const text = latestNote.params.text || "[Пустая заметка]";

    // Отдаем дальше ОДИН объект с самой свежей информацией
    return [{
        json: {
            note_id: latestNote.id,
            created_at_formatted: dateStr,
            note_type: latestNote.note_type,
            text: text
        }
    }];

} catch (error) {
    return [{ 
        json: { 
            error_status: true,
            error_message: "Ошибка парсинга: " + error.message 
        } 
    }];
}

